 controls[6]=1;for(int i=0;i<20;++i)CHECK(dango_belt_step(h,1.0f/120,controls,9)==0);CHECK(read_frame(h)==0);CHECK(fabs(stats[19]-config.downward_force)<1e-5&&stats[23]>stats[5]);controls[6]=0;controls[1]=1;CHECK(dango_belt_step(h,1.0f/120,controls,9)==0);CHECK(read_frame(h)==0);CHECK(stats[17]==0&&fabs(stats[19]+config.downward_force)<1e-5);controls[1]=0;
 controls[0]=1;CHECK(dango_belt_step(h,1.0f/120,controls,9)==0);CHECK(read_frame(h)==0);CHECK(fabs(stats[18]-stats[57])<1e-6&&stats[18]>0);CHECK(stats[20]>stats[4]);
 for(int i=0;i<120;++i)CHECK(dango_belt_step(h,1.0f/120,controls,9)==0);memset(controls,0,sizeof controls);for(int i=0;i<240;++i)CHECK(dango_belt_step(h,1.0f/120,controls,9)==0);
 CHECK(read_frame(h)==0);controls[2]=1;CHECK(dango_belt_step(h,1.0f/120,controls,9)==0);CHECK(read_frame(h)==0);CHECK(stats[15]==1&&stats[47]>0);controls[2]=0;int airborne=0;double peak_gap=-1e6,peak_core=-1e6,peak_center=-1e6;for(int i=0;i<120;++i){CHECK(dango_belt_step(h,1.0f/120,controls,9)==0);CHECK(read_frame(h)==0);peak_gap=fmax(peak_gap,stats[12]);peak_core=fmax(peak_core,stats[1]);peak_center=fmax(peak_center,stats[3]);if(stats[12]>.0001){airborne=1;break;}}printf("jump peakGap=%.9g peakCoreY=%.9g peakBeltCenterY=%.9g\n",peak_gap,peak_core,peak_center);CHECK(airborne);controls[0]=1;CHECK(dango_belt_step(h,1.0f/120,controls,9)==0);CHECK(read_frame(h)==0);CHECK(fabs(stats[18]-config.horizontal_force*config.air_control_ratio)<1e-5);
